// 模擬溫度 (22.0 ~ 28.0 °C) 與濕度 (45 ~ 70 %)
const temp = Number((22 + Math.random() * 6).toFixed(1));
const hum = Math.floor(45 + Math.random() * 26);

const msgTemp = {
    topic: "AIOT/user12/sensor/temperature",
    payload: temp
};

const msgHum = {
    topic: "AIOT/user12/sensor/humidity",
    payload: hum
};

// 依序發送溫度與濕度兩筆 MQTT 訊息
return [[msgTemp, msgHum]];

// Topic 格式: AIOT/user1/sensor/temperature
const parts = msg.topic.split("/");
const groupName = parts[1] || "未知組別";
const sensorType = parts[3] || "未知感測器";

let label = sensorType;
let unit = "";

if (sensorType === "temperature") {
    label = "溫度";
    unit = " °C";
} else if (sensorType === "humidity") {
    label = "濕度";
    unit = " %";
}

msg.payload = `[${groupName} 教室] ${label}: ${msg.payload}${unit}`;
return msg;

if (flow.get("autoSim") === false) return null;

const temp = Number((22 + Math.random() * 6).toFixed(1));
const hum = Math.floor(45 + Math.random() * 26);

const msgTemp = {
    topic: "AIOT/user12/sensor/temperature",
    payload: temp
};

const msgHum = {
    topic: "AIOT/user12/sensor/humidity",
    payload: hum
};

return [[msgTemp, msgHum]];

// Topic 格式: AIOT/user12/sensor/temperature
const parts = msg.topic.split("/");
const groupName = parts[1] || "未知組別";
const sensorType = parts[3] || "未知感測器";
const val = Number(msg.payload);

let label = sensorType;
let unit = "";
if (sensorType === "temperature") {
    label = "溫度";
    unit = " °C";
} else if (sensorType === "humidity") {
    label = "濕度";
    unit = " %";
}

const logMsg = {
    payload: `[${groupName} 教室] ${label}: ${msg.payload}${unit}`
};

let outTemp = null;
let outHum = null;

if (groupName === "user12" && !isNaN(val)) {
    if (sensorType === "temperature") {
        flow.set("latestTemp", val);
        outTemp = { topic: "溫度 (°C)", payload: val };
    } else if (sensorType === "humidity") {
        flow.set("latestHum", val);
        outHum = { topic: "濕度 (%)", payload: val };
    }
}

return [outTemp, outHum, logMsg];

const apiKey = "請填入你的_GEMINI_API_KEY";
const temp = flow.get("latestTemp") ?? "未知";
const hum = flow.get("latestHum") ?? "未知";

msg.url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    contents: [{
        parts: [{
            text: `你是一位智慧教室節能顧問。目前教室溫度為 ${temp} °C、相對濕度為 ${hum} %。請用繁體中文給出 45 字以內的具體冷氣、除濕或通風節能建議，語氣自然親切。`
        }]
    }]
};
return msg;

if (msg.payload && msg.payload.error) {
    return { payload: "AI 錯誤：" + msg.payload.error.message };
}
try {
    const reply = msg.payload.candidates[0].content.parts[0].text;
    return { payload: reply.trim() };
} catch (e) {
    return { payload: "無法取得 AI 建議，請檢查 API Key 或網路連線。" };
}

const raw = msg.payload;
let brightness = 0;

if (raw === "ON" || raw === "on" || raw === true) {
    brightness = 100;
} else if (raw === "OFF" || raw === "off" || raw === false) {
    brightness = 0;
} else {
    brightness = Math.max(0, Math.min(100, Number(raw) || 0));
}

const statusText = brightness > 0
    ? `💡 燈光已開啟（亮度 ${brightness}%）`
    : `⚫ 燈光已關閉（亮度 0%）`;

// 輸出 1：透過 MQTT 回傳執行結果到 status/led
const msgMqttBack = {
    topic: "AIOT/user12/status/led",
    payload: statusText
};

// 輸出 2：更新 Dashboard 模擬燈泡儀表
const msgGauge = {
    payload: brightness
};

// 輸出 3：更新設備端執行紀錄
const msgLog = {
    payload: `[已回傳 MQTT] ${statusText}`
};

return [msgMqttBack, msgGauge, msgLog];

const now = Date.now();
const lastSend = flow.get("lastSendTime") || 0;
if (now - lastSend < 1500) return null;
flow.set("lastSendTime", now);

const cat = flow.get("msgCat") || "announcement";
const rawText = (flow.get("msgText") || "").trim();
const content = rawText !== "" ? rawText : "大家好，這是來自 user12 的測試廣播！";

flow.set("msgText", "");

const mqttMsg = {
    topic: `AIOT/user12/message/${cat}`,
    payload: content
};

const clearInput = {
    payload: ""
};

const feedbackMsg = {
    payload: `✅ 已發送至 AIOT/user12/message/${cat}`
};

return [mqttMsg, clearInput, feedbackMsg];

const parts = msg.topic.split("/");
const sender = parts[1] || "未知同學";
const category = parts[3] || "status";

let text = "";
if (typeof msg.payload === "object" && msg.payload !== null) {
    text = msg.payload.message || msg.payload.msg || msg.payload.text || msg.payload.status || JSON.stringify(msg.payload);
} else {
    text = String(msg.payload);
}

// 接收端自動去重：1.5 秒內相同內容不重複寫入
const now = Date.now();
const msgKey = `${sender}|${category}|${text}`;
const lastKey = flow.get("lastRecvKey") || "";
const lastTime = flow.get("lastRecvTime") || 0;
if (msgKey === lastKey && (now - lastTime) < 1500) {
    return null;
}
flow.set("lastRecvKey", msgKey);
flow.set("lastRecvTime", now);

const d = new Date();
const timeStr = d.toTimeString().slice(0, 8);

const board = flow.get("boardState") || {
    latest: { sender: "-", category: "等待中", text: "等待全班廣播訊息...", time: "--:--:--" },
    ann: { sender: "-", text: "尚無公告訊息", time: "" },
    alert: { sender: "-", text: "目前無緊急警報", time: "" },
    status: { sender: "-", text: "尚無狀態回報", time: "" },
    history: []
};

const item = { sender, category, text, time: timeStr };
board.latest = item;

if (category === "announcement") {
    board.ann = item;
} else if (category === "alert") {
    board.alert = item;
} else {
    board.status = item;
}

board.history.unshift(item);
if (board.history.length > 5) {
    board.history = board.history.slice(0, 5);
}

flow.set("boardState", board);

const outBoard = { payload: board };
const outAlert = category === "alert" ? { payload: `🚨 [${sender}] ${text}` } : null;
const outDebug = { payload: `[${timeStr}] [${sender}｜${category}] ${text}` };

return [outBoard, outAlert, outDebug];
